package hype.s23.camera;
import android.app.Activity;import android.os.Bundle;import android.content.pm.PackageManager;import android.hardware.camera2.CameraCharacteristics;import android.widget.*;import android.view.*;
public final class MainActivity extends Activity {
 private TextView output;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,48,32,32);TextView title=new TextView(this);title.setText("Samsung Camera Enhancement\n2.1 Experimental • @s23_hype");title.setTextSize(24);l.addView(title);TextView note=new TextView(this);note.setText("Enable this module in LSPosed and select Samsung Camera only. Force stop Camera and reopen. This screen scans hardware; it cannot confirm the hook is active. Check LSPosed logs for that.");l.addView(note);Button scan=new Button(this);scan.setText("Scan camera profiles");l.addView(scan);output=new TextView(this);output.setTextIsSelectable(true);l.addView(output);ScrollView s=new ScrollView(this);s.addView(l);setContentView(s);scan.setOnClickListener(v->{if(checkSelfPermission(android.Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.CAMERA},1);else scan();});}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==1&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)scan();}
 private void scan(){output.setText("Scanning…");new Thread(()->{String report="Model: "+android.os.Build.MODEL+"\nRear: "+Capabilities.scan(this,CameraCharacteristics.LENS_FACING_BACK)+"\nFront: "+Capabilities.scan(this,CameraCharacteristics.LENS_FACING_FRONT)+"\nHigh-speed-only ranges (not unlocked in normal Pro Video):\n"+Capabilities.highSpeed(this)+"\nVideo HDR rear: "+Capabilities.allHdr(this,true)+"\nPhoto HDR rear: "+Capabilities.allHdr(this,false)+"\nNormal-mode candidates, not tested recordings. Empty does not prove hardware is incapable.";runOnUiThread(()->output.setText(report));}).start();}
}
